window.OGE_TASKS_BY_NUMBER.english = [{"num": "1-4", "shortTitle": "Аудирование (1-4)", "part": "Раздел 1 (Аудирование)", "title": "Задания № 1–4: Выбор ответа к 4 коротким диалогам", "fipiSpec": {"number": "№ 1-4", "score": "4 балла", "time": "6 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<p>Вы услышите 4 коротких диалога (2 раза). К каждому — 1 вопрос с 3 вариантами ответа.</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Заранее прочитайте вопросы до начала записи:</strong> Подчеркните ключевые слова (место, время, цена, причина).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Слушайте ловушки-отрицания:</strong> Часто диктор сначала называет один вариант («I wanted to go on Monday, BUT...»), а правильный идёт после «but / however / actually»!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Where do the speakers decide to meet? A) Café B) Park C) Museum</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>В аудио: «Let's meet at the café? No, it's noisy, let's go to the park».</p><div class=\"task-answer-box\">Ответ: <strong>2 (Park)</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Первый услышанный вариант</strong><p>Самый первый упомянутый вариант почти всегда является ловушкой-отвлечением!</p></div>"}, {"num": "5", "shortTitle": "Аудирование (5)", "part": "Раздел 1 (Аудирование)", "title": "Задание № 5: Сопоставление 5 говорящих (A–E) и 6 рубрик/тем", "fipiSpec": {"number": "№ 5", "score": "5 баллов", "time": "6 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<p>Пять человек высказываются на общую тему. Нужно сопоставить каждого с одним из 6 заголовков (один заголовок лишний!).</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Переведите все 6 заголовков:</strong> Выделите, чем они отличаются друг от друга.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Ловите главную мысль, а не отдельные слова:</strong> Часто в речи используется синоним вместо слова из заголовка.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> 5 спикеров говорят о любимых видах спорта.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Сопоставляем синонимы: «swimming in the sea» → water sports.</p><div class=\"task-answer-box\">Ответ: <strong>5 цифр</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Повтор слова из заголовка</strong><p>Если спикер сказал точное слово из заголовка — проверьте контекст, возможно, он сказал, что НЕ любит это!</p></div>"}, {"num": "6-11", "shortTitle": "Аудирование (6-11)", "part": "Раздел 1 (Аудирование)", "title": "Задания № 6–11: Интервью и заполнение таблицы (1 слово / число)", "fipiSpec": {"number": "№ 6-11", "score": "6 баллов", "time": "8 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<p>Звучит интервью. Нужно вписать в пропуски 6–11 <strong>ровно ОДНО слово</strong> (или число, записанное буквами/цифрами по инструкции, обычно без артиклей!). Внимание на орфографию!</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Определите часть речи для каждого пропуска:</strong> Существительное, прилагательное, числительное или день недели/месяц.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Записывайте без артиклей (a/the):</strong> Соблюдайте правильное написание (Tuesday, Wednesday, February, library).</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Age: ___; Favourite hobby: ___.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Вписываем только слово без пробелов, например: <code>15</code>, <code>cycling</code>.</p><div class=\"task-answer-box\">Ответ: <strong>Одно слово без артикля</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Число прописью vs цифрой</strong><p>В ОГЭ в заданиях 6–11 числительные рекомендуется писать СЛОВОМ (например: <code>fifteen</code>), но проверяйте инструкцию в КИМе!</p></div>"}, {"num": "12", "shortTitle": "Чтение (12)", "part": "Раздел 2 (Чтение)", "title": "Задание № 12: Подбор 6 заголовков (вопросов) к 6 текстам (1 лишний)", "fipiSpec": {"number": "№ 12", "score": "6 баллов", "time": "10 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<p>Шесть коротких текстов (A–F) и 7 вопросов (1–7). На каждый вопрос отвечает ровно один текст.</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Прочитайте сначала все 7 вопросов:</strong> Читайте текст A и сразу подбирайте ему подходящий вопрос.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> 7 вопросов про историю изобретения велосипеда.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Ищем ключевые ответы на вопрос в каждом абзаце.</p><div class=\"task-answer-box\">Ответ: <strong>6 цифр</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Незаполненный пропуск</strong><p>Проверьте, что одна цифра осталась лишней, и ни одна не повторилась!</p></div>"}, {"num": "13-19", "shortTitle": "Чтение (True/False/NS)", "part": "Раздел 2 (Чтение)", "title": "Задания № 13–19: Анализ текста (1-True, 2-False, 3-Not Stated)", "fipiSpec": {"number": "№ 13-19", "score": "7 баллов", "time": "15 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<div class='task-formula-box'><div class='math-row'>• <strong>1 (True):</strong> в тексте есть прямое подтверждение.<br>• <strong>2 (False):</strong> в тексте прямо написано ПРОТИВОПОЛОЖНОЕ.<br>• <strong>3 (Not Stated):</strong> в тексте об этом ВООБЩЕ не сказано (ни «да», ни «нет» — нельзя ни подтвердить, ни опровергнуть!).</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Ищите точное место в тексте:</strong> Вопросы идут строго по порядку абзацев текста!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Текст: «John bought a red car». Утверждение: «John's car was expensive».</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Про цену не сказано ни слова → Not Stated (3)!</p><div class=\"task-answer-box\">Ответ: <strong>3</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ False vs Not Stated</strong><p>Если в тексте нет информации — это 3 (Not Stated), а НЕ False!</p></div>"}, {"num": "20-28", "shortTitle": "Грамматика (20-28)", "part": "Раздел 3 (Грамматика)", "title": "Задания № 20–28: Изменение грамматической формы слова", "fipiSpec": {"number": "№ 20-28", "score": "9 баллов", "time": "12 мин", "difficulty": "Базовый", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Все возможные превращения в 20–28</h4>\n     <div class='task-formula-box'><div class='math-row'>• <strong>Существительное:</strong> мн. число (исключения: <em>children, men, women, feet, teeth, mice, sheep, people</em>).<br>• <strong>Числительное:</strong> порядковое (<em>first, second, third, fifth, twelfth</em>).<br>• <strong>Местоимение:</strong> объектный/притяжательный/возвратный падеж (<em>I → me/my/myself</em>).<br>• <strong>Прилагательное/Наречие:</strong> степени сравнения (<em>good → better → the best; bad → worse → the worst</em>).<br>• <strong>Глагол:</strong> время (Past Simple, Present Perfect, Past Continuous, Future), <strong>Passive Voice</strong> (was built, is spoken), <strong>I wish</strong> (+ Past Simple: wished/were) или <strong>Условные (If)</strong>!</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Определите часть речи опорного слова:</strong> Нельзя менять часть речи (например, из глагола делать существительное — это уже №29–34!).</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> If I (BE) you, I would go there.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>2-й тип условных предложений → <code>were</code> (или was).</p><div class=\"task-answer-box\">Ответ: <strong>were</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Passive Voice (страдательный залог)</strong><p>Если подлежащее НЕ может делать действие само («The book (WRITE) in 1990»), нужен пассив: <code>was written</code>!</p></div>"}, {"num": "29-34", "shortTitle": "Словообразование (29-34)", "part": "Раздел 3 (Лексика)", "title": "Задания № 29–34: Образование нового однокоренного слова (суффиксы и приставки)", "fipiSpec": {"number": "№ 29-34", "score": "6 баллов", "time": "10 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Главные суффиксы и приставки</h4>\n     <div class='task-formula-box'><div class='math-row'>• <strong>Существительные:</strong> -tion/-sion, -ment, -ness, -ity, -er/-or, -ist.<br>• <strong>Прилагательные:</strong> -ful, -less (отсутствие), -ous, -al, -ive, -able, -y.<br>• <strong>Наречия:</strong> -ly (быстро: quick → quickly).<br>• <strong>Отрицательные приставки:</strong> un-, in-, im- (перед p/m), ir- (перед r), il- (перед l), dis-.</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Определите по смыслу, какая часть речи нужна в пропуске:</strong> Перед существительным — прилагательное; после глагола — наречие; нужен антоним — приставка un-/in-!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> He answered very (POLITE) — everyone was offended.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>После глагола нужно наречие + по смыслу отрицание → <code>impolitely</code>.</p><div class=\"task-answer-box\">Ответ: <strong>impolitely</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Окончание на -y / -e</strong><p>При добавлении суффиксов проверяйте чередования: happy → happily, beauty → beautiful.</p></div>"}, {"num": "35", "shortTitle": "Электронное письмо (35)", "part": "Раздел 4 (Письмо)", "title": "Задание № 35: Написание электронного письма другу (100–120 слов)", "fipiSpec": {"number": "№ 35", "score": "10 баллов", "time": "30 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Универсальный шаблон письма (10/10 баллов)</h4>\n     <div class='task-formula-box'><div class='math-row'><strong>Структура (строго 100–120 слов, допустимо 90–132!):</strong><br>1. <strong>Обращение</strong> (отдельная строка + запятая): <code>Dear Ben,</code><br>2. <strong>Благодарность</strong> + ссылка на прошлый контакт: <code>Thanks for your email. It was great to hear from you again.</code><br>3. <strong>Ответы на ВСЕ 3 вопроса</strong> друга полными предложениями.<br>4. <strong>Завершение + фраза о будущих контактах:</strong> <code>Write back soon.</code><br>5. <strong>Прощание (без точки!) + Имя:</strong> <code>Best wishes,</code><br><code>Alex</code></div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Пересчитайте слова!:</strong> Меньше 90 слов = 0 баллов! Больше 132 = проверяют только первые 120 слов (прощание отрежут!).</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Не пишите адрес и дату:</strong> В электронном письме ОГЭ адрес и дата НЕ нужны!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Друг задал 3 вопроса про спорт и школу.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Отвечаем на все 3 вопроса по очереди в основном абзаце с мостиками.</p><div class=\"task-answer-box\">Ответ: <strong>10 баллов</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Знаки препинания в конце</strong><p>После имени подпись без точки! После Best wishes, — запятая! В вопросе друга 3 подвопроса — не пропустите ни один!</p></div>"}, {"num": "36-38 (Устн.)", "shortTitle": "Устная часть (1, 2, 3)", "part": "Раздел 5 (Говорение)", "title": "Устная часть ОГЭ: 1) Чтение текста; 2) Ответы на 6 вопросов; 3) Монолог", "fipiSpec": {"number": "№ 36-38 (Устн.)", "score": "15 баллов", "time": "15 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Как сдать устную часть на максимум (15 баллов)</h4>\n     <div class='task-formula-box'><div class='math-row\">• <strong>Задание 1 (Чтение, 2 б.):</strong> Читайте чётко, не торопитесь, соблюдайте паузы и ударения, не глотайте окончания -s/-ed и числа.<br>• <strong>Задание 2 (6 вопросов телефонного опроса, 6 б.):</strong> Отвечайте ПОЛНЫМ предложением (а не одним словом «Yes» или «Football»!). Например: <em>«My favourite subject is Maths because I like solving problems.»</em><br>• <strong>Задание 3 (Монолог, 7 б.):</strong> 10–12 фраз (1,5–2 минуты). Обязательно раскройте <strong>все 4 пункта плана</strong> + вступление + заключение!</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>В монологе используйте связки:</strong> <code>I am going to give a talk about...</code>, <code>First of all...</code>, <code>As for...</code>, <code>To sum up, ... That is all I wanted to say.</code></div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ (Монолог)</div><p><strong>Условие:</strong> Расскажите о свободном времени (4 пункта).</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Вступление → 4 пункта (по 2–3 предложения на каждый) → заключение.</p><div class=\"task-answer-box\">Ответ: <strong>15 баллов</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Краткий ответ в Задании 2</strong><p>В телефонном опросе нельзя отвечать фразой из 1–2 слов — всегда стройте полное грамматически правильное предложение!</p></div>"}];
window.OGE_TASKS_BY_NUMBER.literature = [{"num": "1", "shortTitle": "Анализ фрагмента (1)", "part": "Часть 1", "title": "Задание № 1: Развёрнутый ответ по эпизоду эпического/драматического произведения (1.1 или 1.2)", "fipiSpec": {"number": "№ 1", "score": "4–6 баллов", "time": "25 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<p>Вам даётся 2 вопроса на выбор (1.1 и 1.2) по приведённому фрагменту прозы/пьесы. Нужно дать связный ответ (5–10 предложений), опираясь на текст и не искажая авторскую позицию.</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Выберите более понятный вопрос (1.1 или 1.2):</strong> Сразу дайте прямой ответ в первом предложении.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Опирайтесь на текст:</strong> Приведите 1–2 короткие цитаты или конкретные детали из фрагмента, не пересказывая сюжет!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Как проявляется характер Хлестакова в приведённой сцене «Ревизора»?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Тезис (легкомыслие, хвастовство) → анализ его реплик в сцене → вывод об авторской иронии.</p><div class=\"task-answer-box\">Ответ: <strong>Связной ответ</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Пересказ вместо анализа</strong><p>Главное правило ОГЭ по литературе: отвечайте на вопрос «почему/зачем», а не просто пересказывайте, кто куда пошёл!</p></div>"}, {"num": "2", "shortTitle": "Анализ другого фрагмента (2)", "part": "Часть 1", "title": "Задание № 2: Выбор и анализ другого эпизода того же произведения (2.1 или 2.2)", "fipiSpec": {"number": "№ 2", "score": "4–6 баллов", "time": "25 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<p>Нужно вспомнить <strong>другой</strong> фрагмент этого же произведения (текста этого эпизода нет на столе!) и проанализировать его в заданном ракурсе.</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Выберите яркий ключевой эпизод:</strong> Например, для «Капитанской дочки» — встреча в буран или суд; для «Евгения Онегина» — дуэль или письмо Татьяны.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Укажите точные имена и события:</strong> Избегайте фактических ошибок (перепутать имена, места или детали = −1 балл!).</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Приведите другой эпизод из «Евгения Онегина», где проявляется душевная глубина Татьяны.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Эпизод объяснения в саду или финальная встреча в Петербурге (верность долгу: «но я другому отдана; я буду век ему верна»).</p><div class=\"task-answer-box\">Ответ: <strong>Связанный анализ</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Фактические ошибки</strong><p>Не придумывайте детали, если не уверены в точности — пишите только то, что знаете наверняка!</p></div>"}, {"num": "3", "shortTitle": "Анализ стихотворения (3)", "part": "Часть 1", "title": "Задание № 3: Развёрнутый ответ по приведённому лирическому стихотворению (3.1 или 3.2)", "fipiSpec": {"number": "№ 3", "score": "4–6 баллов", "time": "25 мин", "difficulty": "Повышенный", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<div class='task-formula-box'><div class='math-row'><strong>Что искать в стихе:</strong> лирический герой (его чувства: тоска, восторг, одиночество), тропы (метафора, эпитет, сравнение, олицетворение, антитеза, анафора) и их роль!</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Определите тему и настроение стиха:</strong> Пейзажная, любовная, гражданская или философская лирика.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Назовите 2–3 средства выразительности с цитатами:</strong> Объясните, ЗАЧЕМ поэт их использует.</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Какую роль играет антитеза в стихотворении Лермонтова «Парус»?</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Противопоставление «лазури и луча» и «бури» отражает мятежную душу лирического героя.</p><div class=\"task-answer-box\">Ответ: <strong>Анализ лирики</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Отождествление автора и лирического героя</strong><p>Пишите «лирический герой чувствует...», а не «Лермонтов чувствует...» (в стихотворении действует лирический герой!).</p></div>"}, {"num": "4", "shortTitle": "Сопоставление стихов (4)", "part": "Часть 1", "title": "Задание № 4: Сопоставление двух стихотворений (черта сходства и/или различия)", "fipiSpec": {"number": "№ 4", "score": "6–8 баллов", "time": "30 мин", "difficulty": "Высокий", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<p>К первому стихотворению даётся второе. Нужно сопоставить их по теме, образам или настроению (что общего и в чём отличие).</p>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Найдите 1–2 общие черты и 1–2 различия:</strong> Обязательно ссылайтесь на ОБА стихотворения в каждом сравнительном абзаце (используйте связки: «В отличие от...», «Как и в первом стихотворении...»).</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Сравните образы природы у Тютчева и Фета.</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Сходство — одухотворение природы; различие — у Тютчева природа драматична, у Фета — гармонична и созерцательна.</p><div class=\"task-answer-box\">Ответ: <strong>Сопоставительный анализ</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Анализ текстов по отдельности</strong><p>Если сначала написать 10 строк про 1-й стих, а потом 10 про 2-й без сопоставления — балл резко снизят!</p></div>"}, {"num": "5", "shortTitle": "Большое сочинение (5)", "part": "Часть 2", "title": "Задание № 5: Полноформатное сочинение (5.1, 5.2, 5.3, 5.4 или 5.5 — минимум 150–200 слов)", "fipiSpec": {"number": "№ 5", "score": "13–16 баллов", "time": "90 мин", "difficulty": "Высокий", "docSource": "Кодификатор и открытый банк ФИПИ ОГЭ 2026/2027"}, "theory": "<h4>Главное задание экзамена (самый высокий вес!)</h4>\n      <div class='task-formula-box'><div class='math-row'>На выбор 5 тем (от древнерусской/XVIII в. до современной литературы и тем по выбору). Рекомендуемый объём: <strong>200–250 слов</strong> (минимум 150 слов, иначе оценка резко падает!).</div></div>", "algorithm": "<div class=\"task-step-list\"><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 1</div><div class=\"task-step-desc\"><strong>Составьте чёткий план из 3–4 частей:</strong> 1) Вступление с тезисом (ответом на вопрос); 2) 2–3 аргумента с анализом эпизодов/образов и <strong>теоретико-литературными понятиями</strong> (конфликт, композиция, символ, деталь, пейзаж); 3) Вывод.</div></div><div class=\"task-step-item\"><div class=\"task-step-num\">Шаг 2</div><div class=\"task-step-desc\"><strong>Используйте минимум 3–4 термина уместно:</strong> Это даёт полные баллы по критерию использования терминов!</div></div></div>", "examples": "<div class=\"task-example-card\"><div class=\"task-example-badge\">ФИПИ</div><p><strong>Условие:</strong> Тема 5.2: Роль эпиграфов в романе А.С. Пушкина «Капитанская дочка».</p><div class=\"task-example-solution\"><strong>Решение:</strong><p>Тезис: эпиграфы предвосхищают сюжет и раскрывают нравственную идею. Разбор общего эпиграфа «Береги честь смолоду» и эпиграфов к главам → вывод.</p><div class=\"task-answer-box\">Ответ: <strong>16 баллов</strong></div></div></div>", "traps": "<div class=\"callout callout-warning\"><strong>⚠️ Малый объём или отсутствие терминов</strong><p>Если в сочинении меньше 150 слов — за содержание ставят 0 баллов! Всегда пересчитывайте слова перед сдачей!</p></div>"}];
